const order = $json;
const money = (amount) => new Intl.NumberFormat('es-CO', { style: 'currency', currency: order.currency, minimumFractionDigits: 0 }).format(amount);
const isReceipt = order.payment_status === 'pending_verification';
const shortId = order.id.slice(0, 8);

const rows = order.items
  .map((item) => `<tr><td>${item.name}</td><td align="center">${item.quantity}</td><td align="right">${money(item.unit_price * item.quantity)}</td></tr>`)
  .join('');

const subject = isReceipt
  ? `Comprobante recibido — pedido #${shortId}`
  : `Nuevo pedido #${shortId} de ${order.buyer_name}`;

const intro = isReceipt
  ? `${order.buyer_name} subió el comprobante de pago del pedido <b>#${shortId}</b>. Revísalo y apruébalo o recházalo en Studio.`
  : `Tienes un pedido nuevo de <b>${order.buyer_name}</b>.`;

const receipt = isReceipt
  ? `<p>Número de transferencia: <b>${order.transfer_number ?? '—'}</b></p>`
  : '';

const html = `<p>Hola ${order.seller_name},</p>
<p>${intro}</p>
<table cellpadding="6" style="border-collapse:collapse" border="1">
<tr><th align="left">Producto</th><th>Cant.</th><th align="right">Subtotal</th></tr>${rows}
<tr><td colspan="2"><b>Total</b></td><td align="right"><b>${money(order.total)}</b></td></tr>
</table>${receipt}
<p style="color:#666">Mensaje automático de Libra.</p>`;

return { json: { to: order.seller_email, subject, html, order_id: order.id, kind: isReceipt ? 'receipt' : 'created' } };
